from _lib import File
F=File('pre2020_gaps5','o-gu','Fifth fill of uncovered pre-2020 off-road years from model-year change announcements and spec listings: KTM XC/XC-W/XC-F 2011-2016, Husqvarna TE/FE 2015 and 2019, Yamaha WR450F 2010-2011 (knowledge push 2026-11)','KTM',['250 XC'],list(range(2010,2020)))
R=F.R; K='KTM'; Q='Husqvarna'; A='article'; M='magazine'
s=F.src(A,"Total Motorcycle - 2013 KTM 250 XC-W","https://www.totalmotorcycle.com/motorcycles/2013models/2013-KTM-250XCW","2013")
R('identity','250 XC-W 2013 updates and specs',['250 XC-W'],[2013],"For 2013 the 250 XC-W got V-Force 4 reed blocks, the DDS clutch with a one-piece steel outer hub and Brembo hydraulics, electric start as standard alongside the kickstarter, and a tool-free airbox. It has a switchable ignition curve (standard or softer) and the power delivery can be tuned with the exhaust-control springs. It uses a 48 mm WP fork (300 mm travel) and a PDS shock (335 mm), 13/50 gearing and a 2.6-gallon tank, with a 960 mm seat and about 225 lb without fuel. US list price $8,199.",{'gearing':'13/50','travel_mm':'300 / 335','tank_gal':2.6,'weight_lb_no_fuel':225,'seat_mm':960,'msrp_usd':8199},'OEM',s,make=K)
s=F.src(A,"TopSpeed - 2014 KTM 250 XC-W","https://www.topspeed.com/motorcycles/motorcycle-reviews/ktm/2014-ktm-250-xc-w-ar160373/pictures.html","2014")
R('identity','250 XC-W 2014 updates and specs',['250 XC-W'],[2014],"For 2014 the 250 XC-W got a redesigned reed housing with Boyesen reeds, an optimised ignition curve and cylinder head with matching carburettor settings, a 4 Ah battery in place of the 3 Ah one for surer starting, a lighter chain guide, a front brake master cylinder with a smaller piston and new pads, and a stiffer, rib-free front fender. It keeps the PDS shock (335 mm travel) and 48 mm fork (300 mm), runs 60:1 premix, holds 2.6 gallons and weighs 225.1 lb without fuel.",{'battery_ah':'4 (was 3)','premix':'60:1','tank_gal':2.6,'weight_lb_no_fuel':225.1},'OEM',s,make=K)
s=F.src(M,"Cycle News - 2015 KTM XC-W first look","https://www.cyclenews.com/2014/06/article/first-look-2015-ktm-xc-ws-and-exc-dual-sports/","2014")
R('identity','250 XC-W and 300 XC-W 2015 updates',['250 XC-W','300 XC-W'],[2015],"For 2015 both the 250 XC-W and 300 XC-W got new carburettor settings, a lighter 3 Ah battery, shorter starter gearing for more cranking torque, and new ignition-cover and inner-clutch-cover gaskets. The 250 also had its power-valve opening point moved 200 rpm higher with a matching CDI curve. Both gained a new digital speedometer, black rims and bar, stronger handguards, softer grips and an orange frame.",{'pv_250':'opens 200 rpm later','battery_ah':3},'OEM',s,make=K)
s=F.src(M,"Cycle News - 2015 KTM XCs first look","https://cyclenews.com/2014/06/article/first-look-2015-ktm-xcs","2014")
R('identity','XC and XC-F 2015 chassis updates',['250 XC','300 XC','250 XC-F','350 XC-F','450 XC-F'],[2015],"All 2015 KTM XC models got a 4CS fork 8 mm longer with a new hydraulic stop, new pistons and a 20 N/mm chamber spring (was 18), a re-valved shock with 4 mm more shaft travel, new linkage geometry, a 22 mm front axle in place of the 26 mm one (moved back 2 mm), a lighter rear sprocket and a frame with a machined cross tube. The two-strokes and the 250 and 350 XC-F got a lighter clutch basket; the 250 and 350 XC-F also got new clutch springs. The 450 XC-F stayed a five-speed SOHC; the 250 and 350 are six-speed DOHC engines.",{'fork_chamber_spring':'20 N/mm (was 18)','front_axle_mm':'22 (was 26)','shock':'+4 mm shaft travel'},'OEM',s,make=K)
s=F.src(A,"Total Motorcycle - 2016 KTM 300 XC","https://www.totalmotorcycle.com/motorcycles/2016/2016-KTM-300-XC","2016")
R('identity','300 XC 2016 updates and specs',['300 XC'],[2016],"The 2016 300 XC kept the 2015 engine and chassis with detail changes: a rubber-damped upper triple clamp for the bar mounts, a larger bar pad and lighter wave brake discs. It runs a Keihin PWK 38 carburettor, six-speed gearbox, kick and electric start, DDS clutch with Brembo hydraulics, a 48 mm WP 4CS fork and linkage shock (300 / 317 mm travel), 13/50 gearing and a 10-litre tank, and weighs 100.7 kg without fuel.",{'carb':'Keihin PWK 38S AG','gearing':'13/50','tank_l':10,'weight_kg_no_fuel':100.7},'OEM',s,make=K)
s=F.src(A,"Motorcycle.com - 2014 KTM 300 XC specifications","https://www.motorcycle.com/specs/ktm/off-road/2014/xc/300/detail.html","2014")
R('identity','300 XC 2014 specs',['300 XC'],[2014],"The 2014 300 XC is a 293.2 cc (72 x 72 mm) two-stroke with electric and kick start and a six-speed gearbox, a 48 mm WP fork (300 mm travel) and a single shock with 317 mm of rear travel, a 2.6-gallon tank and a 39.1 in seat. The spec listing gives a 36 mm Keihin, 229.1 lb dry and a $8,499 list price.",{'carb':'Keihin 36 mm (per listing)','dry_weight_lb':229.1,'tank_gal':2.6,'seat_in':39.1,'msrp_usd':8499},'OEM',s,'low',make=K)
s=F.src(A,"TopSpeed - 2014 KTM 450 XC-F","https://www.topspeed.com/motorcycles/motorcycle-reviews/ktm/2014-ktm-450-xc-f-ar161939/pictures.html","2014")
R('identity','450 XC-F 2014 updates and specs',['450 XC-F'],[2014],"For 2014 the 450 XC-F got the 48 mm WP 4CS closed-cartridge fork with both adjusters on top, a revised lower triple clamp, a lighter chain guide, a stronger diaphragm spring and built-in damping in the DDS clutch with a new master cylinder, a front brake master cylinder with a smaller piston, a new piston pin, a three-layer head gasket and a lighter camshaft with revised auto-decompression. It is a 449.3 cc SOHC (95 x 63.4 mm, 12.6:1) five-speed with a 2.4-gallon tank and 300 / 317 mm of travel, and weighs 241.4 lb without fuel. The maker lists 60 hp.",{'fork':'WP 4CS 48 mm','gearbox':'5-speed','compression':'12.6:1','tank_gal':2.4,'weight_lb_no_fuel':241.4,'claimed_hp':60},'OEM',s,make=K)
R('identity','450 XC-F 2013 against 2014: gearing and brake',['450 XC-F'],[2013],"Two things the 2014 update changed tell you what a 2013 450 XC-F has: 14/52 final gearing (the 2014 change listing gives a new 13/50 final drive) and a 10 mm front brake master-cylinder piston, which was made smaller for 2014.",{'gearing_2013':'14/52','front_master_piston_mm':10},'OEM',s,'low',make=K)
s=F.src(A,"Powersports Business - two new KTM cross-country models","https://powersportsbusiness.com/?p=1102","2010")
R('identity','250 XC-F and 350 XC-F 2011: what they are',['250 XC-F','350 XC-F'],[2011],"The 2011 250 XC-F and 350 XC-F were built from the 250 and 350 SX-F: the same style of frame and the SX-F engine, changed for cross-country racing with a six-speed gearbox, a 2.51-gallon tank (1.98 on the SX-F), an 18-inch rear wheel, open handguards and a side stand. They reached dealers in January 2011.",{'gearbox':'6-speed','tank_gal':2.51,'rear_wheel_in':18},'OEM',s,make=K)

# Husqvarna 2015
s=F.src(M,"Cycle News - 2015 Husqvarnas first look","https://www.cyclenews.com/2014/06/article/first-look-2015-husqvarnas","2014")
R('identity','TE and FE range 2015 updates',['TE 250','TE 300','FE 350','FE 450','FE 501'],[2015],"All 2015 TE and FE models got a new headlight, front mask and motocross-style front fender, revised black CNC triple clamps, an extra subframe screw on the left for a better airbox seal, stronger handguards as standard and a firmer seat. The four-strokes got new O-rings on the oil-pump suction screen. The TE 250 and TE 300 got shorter starter gearing, a lighter 3 Ah battery and a new inner clutch-cover gasket; the TE 250 also had its power-valve opening point raised 200 rpm with improved carburation. The FE 350 got a lighter clutch basket. No model-specific changes were listed for the FE 450 or FE 501.",{'te250_pv':'opens 200 rpm later','battery_ah':3},'OEM',s,make=Q)
# Husqvarna 2019
s=F.src('press',"Racer X - Husqvarna 2019 enduro lineup announcement","https://racerxonline.com/2018/05/17/husqvarna-announces-2019-enduro-lineup","2018")
R('identity','TE and FE range 2019 updates',['TE 150','FE 350','FE 450','FE 501'],[2019],"For 2019 the Husqvarna enduro models got new, stiffer settings in the WP Xplor 48 fork and WP shock for more bottoming resistance, a clutch cover with better wear resistance and new graphics. The TE 150 got a new diaphragm-spring steel clutch. All the four-strokes have electric start as standard.",{'te150_clutch':'diaphragm steel'},'OEM',s,make=Q)
# Yamaha WR450F 2010-2011
s=F.src(A,"Total Motorcycle - 2011 Yamaha WR450F","https://www.totalmotorcycle.com/photos/2011models/2011-Yamaha-WR450F","2011")
R('identity','WR450F 2011 layout (carbureted five-valve)',['WR450F'],[2011],"The 2011 WR450F is the carbureted model: a 449 cc five-titanium-valve DOHC engine (95.0 x 63.4 mm, 12.3:1) with a 39 mm Keihin FCR-MX flat-slide, electric start with a kick backup and a wide-ratio five-speed, in an aluminium semi-double-cradle frame with a 48 mm Kayaba cartridge fork (11.8 in travel). Seat height 38.6 in, 2.1-gallon tank, 267 lb wet by the US spec. US list price $7,650.",{'carb':'Keihin FCR-MX39','valves':5,'compression':'12.3:1','gearbox':'5-speed wide ratio','seat_in':38.6,'tank_gal':2.1,'wet_weight_lb':267,'msrp_usd':7650},'OEM',s,make='Yamaha')
s=F.src(A,"Total Motorcycle - 2010 Yamaha WR450F","https://www.totalmotorcycle.com/2010-Yamaha-WR450F.htm","2010")
R('identity','WR450F 2010 layout (carbureted five-valve)',['WR450F'],[2010],"The 2010 WR450F is a 449 cc five-titanium-valve DOHC engine (95 x 63.4 mm, 12.3:1) with a 39 mm Keihin FCR-MX flat-slide and throttle position sensor, electric start with a kick backup and a wide-ratio five-speed, in an aluminium semi-double-cradle frame with an adjustable 48 mm fork (300 mm travel) and linkage shock. Seat height 980 mm, 8-litre tank, 124 kg wet. These figures are from the Canadian spec listing.",{'carb':'Keihin FCR-MX39','valves':5,'compression':'12.3:1','gearbox':'5-speed wide ratio','seat_mm':980,'tank_l':8,'wet_weight_kg':124},'OEM',s,'low',make='Yamaha')
if __name__=='__main__': F.write()
